import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// Issue #12: the customer's discount must be applied exactly once.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('customer discount is applied once (under 10 lines)', () => {
  // 1,000 with a 10% customer discount -> 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount (10 lines)', () => {
  // 10 lines, subtotal 10,000: 10% customer discount -> 9,000, then 5% bulk -> 8,550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('no bulk discount at 9 lines, customer discount only', () => {
  // 9 lines, subtotal 9,000: 10% customer discount -> 8,100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('discount rate 0 keeps the total as it was', () => {
  // 10 lines: only the 5% bulk discount; 9 lines: no discount at all
  assert.equal(total(lines(10, 1000), 0), 9500);
  assert.equal(total(lines(10, 1000)), 9500);
  assert.equal(total(lines(9, 1000), 0), 9000);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
